            info.total_allocation_units = (int64_t)(total_bytes.QuadPart / bytes_per_unit);
            info.available_allocation_units = (int64_t)(available_bytes.QuadPart / bytes_per_unit);
            info.sectors_per_unit = sectors_per_cluster;
